return (res) => {
  try {
    const q = String(res.question || '');
    let payload = String(res.answer || '');
    if (!payload) return [q, payload];
    try {
      const arr = JSON.parse(payload);
      if (Array.isArray(arr)) payload = String(arr[arr.length - 1] || '');
    } catch (e) {}
    const norm = (s) => String(s || '').replace(/\s+/g, '');
    const probe = norm(q).slice(0, 24);
    const roots = Array.from(document.querySelectorAll('.questionLi'));
    const root = roots.find((el) => norm(el.textContent).indexOf(probe) >= 0);
    if (!root) return [q, payload];
    const text = payload
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/&num;/g, '#')
      .replace(/&bsol;/g, '\\')
      .replace(/&quot;/g, '"')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&');
    const fire = (el) => {
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
    };
    let done = false;
    Array.from(root.querySelectorAll('textarea')).forEach((ta) => {
      if (done || ta.offsetParent === null) return;
      ta.value = text;
      fire(ta);
      done = true;
    });
    if (!done) {
      Array.from(root.querySelectorAll('iframe')).forEach((fr) => {
        if (done) return;
        const doc = fr.contentDocument;
        if (!doc || !doc.body) return;
        doc.body.innerHTML = payload;
        fire(doc.body);
        done = true;
      });
    }
    return [q, payload];
  } catch (e) {
    return [res.question, res.answer];
  }
};
